// SVG → base64 data URI（小程序 image 不支持 SVG 内联）
const ICONS = {
  shop: {
    normal: '',
    active: ''
  },
  user: {
    normal: '',
    active: ''
  }
}

Component({
  data: {
    selected: 0,
    list: [
      { pagePath: '/pages/index/index', text: '购买', icon: ICONS.shop },
      { pagePath: '/pages/my/my', text: '我的', icon: ICONS.user }
    ]
  },
  methods: {
    onSwitch(e) {
      const idx = e.currentTarget.dataset.index
      const item = this.data.list[idx]
      if (!item || idx === this.data.selected) return
      wx.switchTab({ url: item.pagePath, fail: () => wx.redirectTo({ url: item.pagePath }) })
    }
  }
})